import type { ArgsResult, Command } from './types.ts';

/** Parses argv (program name already removed) into a command. See the scaffold doc comment. */
export function parseArgs(argv: string[]): ArgsResult {
  let json = false;
  let server: string | undefined;
  const words: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '-h' || a === '--help') return { ok: true, args: { command: { kind: 'help' }, json } };
    if (a === '--json') json = true;
    else if (a === '--server' || a.startsWith('--server=')) {
      const v = a === '--server' ? argv[++i] : a.slice('--server='.length);
      if (!v) return { ok: false, error: '--server requires a value' };
      server = v;
    } else if (a.startsWith('-')) return { ok: false, error: `unknown option: ${a}` };
    else words.push(a);
  }

  const [name, arg, ...extra] = words;
  let command: Command;
  let used = 1;
  if (name === undefined || name === 'help') command = { kind: 'help' };
  else if (name === 'stats') command = { kind: 'stats' };
  else if (name === 'shorten' || name === 'lookup') {
    if (arg === undefined) return { ok: false, error: name === 'shorten' ? 'shorten requires a url' : 'lookup requires a code' };
    command = name === 'shorten' ? { kind: 'shorten', url: arg } : { kind: 'lookup', code: arg };
    used = 2;
  } else return { ok: false, error: `unknown command: ${name}` };

  const leftover = used === 1 ? [arg, ...extra].filter((w) => w !== undefined) : extra;
  if (leftover.length) return { ok: false, error: `unexpected argument: ${leftover[0]}` };
  return { ok: true, args: server === undefined ? { command, json } : { command, server, json } };
}
